//! Bus PDOs request a real Object Manager name with FILE_AUTOGENERATED_DEVICE_NAME.

#[test]
fn hosted_io_create_device_publishes_autogenerated_name_for_unnamed_pdo() {
    let reference = include_str!(
        "../../../references/reactos/drivers/bus/acpi/acpienum.c"
    );
    assert!(reference.contains("FILE_AUTOGENERATED_DEVICE_NAME"));

    let driver = include_str!("../../../components/ntos-executive/src/driver_launch.rs");
    let create = &driver[driver.find("extern \"win64\" fn s_io_create_device(").unwrap()..];
    let create = &create[..create.find("\n}\n").unwrap()];
    assert!(create.contains("FILE_AUTOGENERATED_DEVICE_NAME"));
    assert!(create.contains("DeviceFlags::DEVICE_HAS_NAME.bits()"));
    assert!(create.contains("V_NAMED_DEVICE"));

    let broker = &driver[driver.find("if op == HOSTED_DEVICE_OP_CREATE {").unwrap()..];
    let broker = &broker[..broker.find("if op == HOSTED_DEVICE_OP_ATTACH_SAFE {").unwrap()];
    assert!(broker.contains("FILE_AUTOGENERATED_DEVICE_NAME"));
    assert!(broker.contains("next_hosted_autogenerated_device_name()"));
    assert!(broker.contains("name.as_ref()"));
}
